// swift-tools-version: 6.0
import PackageDescription

// rightkit-record macOS helper: a signed Swift binary owned by rightkit-record and launched
// through rightkit-process. It speaks the rightkit-record helper wire protocol (4-byte big-endian
// length, then one JSON object) on stdin/stdout and captures one window with ScreenCaptureKit.
// `build.sh` builds and ad-hoc signs it for tests. Production signing belongs to the release tooling.
let package = Package(
    name: "RightKitRecordMacOS",
    platforms: [.macOS(.v14)],
    products: [
        .executable(name: "rightkit-record-macos-helper", targets: ["rightkit-record-macos-helper"]),
        .executable(name: "rk-fixture-window", targets: ["rk-fixture-window"]),
    ],
    targets: [
        // Pure Foundation: BLAKE3, the frame codec and the protocol messages. No ScreenCaptureKit.
        .target(
            name: "RecordWire",
            swiftSettings: [.unsafeFlags(["-Ounchecked"], .when(configuration: .release))]
        ),
        .executableTarget(
            name: "rightkit-record-macos-helper",
            dependencies: ["RecordWire"]
        ),
        // A tiny AppKit window placed fully off every display, for live tests only.
        .executableTarget(name: "rk-fixture-window"),
        .testTarget(
            name: "RecordWireTests",
            dependencies: ["RecordWire"],
            exclude: ["golden.json"]
        ),
    ],
    swiftLanguageModes: [.v5]
)

// swift-tools-version: 6.0
import PackageDescription

// Neutral macOS CloudKit helper for rightkit-sync (Rust). Speaks the line-JSON
// `rightkit-sync-helper/1` protocol over stdin/stdout and reuses RightKitCloudSync's
// CloudKitSyncTransport (change tags, assets, error classification, account scope).
let package = Package(
    name: "RightKitCloudKitHelper",
    platforms: [.macOS(.v14)],
    products: [
        .executable(name: "rightkit-cloudkit-helper", targets: ["rightkit-cloudkit-helper"]),
    ],
    dependencies: [
        .package(path: "../RightKitSwift"),
    ],
    targets: [
        .executableTarget(
            name: "rightkit-cloudkit-helper",
            dependencies: [.product(name: "RightKitCloudSync", package: "RightKitSwift")]
        ),
    ]
)

// swift-tools-version: 6.3

import PackageDescription

// Vendored from swiftwasm/WasmKit @ 9dc464383ace3773f7883eace2b48ed4340c734a
// (MIT; see LICENSE and NOTICE.txt). This package intentionally exposes only
// the interpreter required by CodeRight's bounded mobile compute tool. CLI,
// WASI, filesystem, Component Model, debugger, and network-adjacent targets
// are excluded. Upstream's warnings-as-errors setting is also excluded because
// Xcode adds -suppress-warnings to dependency targets, which makes the two
// flags mutually incompatible.
let package = Package(
    name: "CodeRightWasmKit",
    platforms: [.iOS(.v18), .macOS(.v15)],
    products: [
        .library(name: "WasmKit", targets: ["WasmKit"]),
    ],
    targets: [
        .target(
            name: "WasmKit",
            dependencies: ["_CWasmKit", "WasmParser", "WasmTypes"],
            exclude: ["CMakeLists.txt"]
        ),
        .target(name: "_CWasmKit"),
        .target(
            name: "WasmParser",
            dependencies: ["WasmTypes"],
            exclude: ["CMakeLists.txt"]
        ),
        .target(name: "WasmTypes", exclude: ["CMakeLists.txt"]),
        .testTarget(name: "CodeRightWasmKitTests", dependencies: ["WasmKit"]),
    ]
)

