// swift-tools-version: 5.10
import PackageDescription

let package = Package(
    name: "HeardRightPillMac",
    platforms: [.macOS(.v13)],
    products: [
        .library(name: "HeardRightPillMac", type: .static, targets: ["HeardRightPillMac"]),
        // Standalone menu bar helper. Packaged as a nested .app under the main
        // bundle's Contents/Library/LoginItems so it carries its own, disposable
        // bundle identifier -- see Sources/HeardRightMenuBar/main.swift.
        .executable(name: "HeardRightMenuBar", targets: ["HeardRightMenuBar"]),
        // Line-delimited-JSON CLI helper driven by the Rust side
        // (src-tauri/src/cloud_sync.rs) to reach CloudKit — Rust cannot call
        // CloudKit directly. See Sources/HeardRightCloudSync/main.swift for
        // the protocol.
        .executable(name: "HeardRightCloudSync", targets: ["HeardRightCloudSync"]),
        // App Shortcuts/App Intents broker. It is packaged as a nested helper
        // and hands validated commands to the running/cold-start desktop app.
        .executable(name: "HeardRightShortcuts", targets: ["HeardRightShortcuts"]),
        // Line-delimited-JSON CLI helper driven by the Rust side
        // (src-tauri/src/pro_bridge.rs) to reach the synchronizable iCloud
        // Keychain for Pro continuity across Apple devices — Rust cannot call
        // Security framework synchronizable-item APIs directly. See
        // Sources/HeardRightAppleCredentials/main.swift for the protocol.
        .executable(name: "HeardRightAppleCredentials", targets: ["HeardRightAppleCredentials"])
    ],
    targets: [
        .target(
            name: "HeardRightPillMacBridge",
            path: "Sources/HeardRightPillMacBridge",
            publicHeadersPath: "include"
        ),
        .target(
            name: "HeardRightPillMac",
            dependencies: ["HeardRightPillMacBridge"],
            path: "Sources/HeardRightPillMac",
            linkerSettings: [
                .linkedFramework("AppKit"),
                .linkedFramework("AVFoundation"),
                .linkedFramework("CoreAudio"),
                .linkedFramework("SwiftUI"),
                .linkedFramework("QuartzCore"),
                .linkedFramework("CoreVideo"),
                .linkedFramework("CloudKit"),
                .linkedFramework("Network"),
                .linkedFramework("UserNotifications")
            ]
        ),
        .executableTarget(
            name: "HeardRightMenuBar",
            path: "Sources/HeardRightMenuBar",
            linkerSettings: [.linkedFramework("AppKit")]
        ),
        .executableTarget(
            name: "HeardRightCloudSync",
            path: "Sources/HeardRightCloudSync",
            linkerSettings: [.linkedFramework("CloudKit")]
        ),
        .executableTarget(
            name: "HeardRightShortcuts",
            path: "Sources/HeardRightShortcuts",
            linkerSettings: [
                .linkedFramework("AppKit"),
                .linkedFramework("AppIntents")
            ]
        ),
        .executableTarget(
            name: "HeardRightAppleCredentials",
            path: "Sources/HeardRightAppleCredentials",
            linkerSettings: [.linkedFramework("Security")]
        ),
        .testTarget(
            name: "HeardRightCloudSyncTests",
            dependencies: ["HeardRightCloudSync"],
            path: "Tests/HeardRightCloudSyncTests"
        ),
        .testTarget(
            name: "HeardRightPillMacTests",
            dependencies: ["HeardRightPillMac"],
            path: "Tests/HeardRightPillMacTests"
        )
    ]
)

