// swift-tools-version:6.0
import PackageDescription

// BridgeGeoModal: two small Windows hosts on the ABI 0.6 bridge (packages/SwiftRightBridge), used for the
// SR0 snapshot rows 6 and 7 on the final tuple:
//   TextGeom06  text geometry (UIA TextPattern vs the measured cells), single- and multi-paragraph text
//   Modal06     the real SWR_MODAL_MENU / SWR_MODAL_DIALOG paths
//   ColdOpen06  (SR0 T10) one modal in a fresh process, with main-queue blocking and request-to-visible measured separately
// Both build on macOS too (they then report "unsupported platform" at run time; SWR_GM_DRYRUN=1 runs only the
// pure-logic self-test there). Windows build needs the ComCtl v6 manifest link flags: see scripts/build.ps1.
let package = Package(
    name: "BridgeGeoModal",
    platforms: [.macOS(.v14)],
    dependencies: [
        .package(path: "../../packages/SwiftRightBridge"),
    ],
    targets: [
        .executableTarget(
            name: "TextGeom06",
            dependencies: [.product(name: "SwiftRightBridge", package: "SwiftRightBridge")],
            path: "Sources/TextGeom06"
        ),
        .executableTarget(
            name: "Modal06",
            dependencies: [.product(name: "SwiftRightBridge", package: "SwiftRightBridge")],
            path: "Sources/Modal06"
        ),
        .executableTarget(
            name: "ColdOpen06",
            dependencies: [.product(name: "SwiftRightBridge", package: "SwiftRightBridge")],
            path: "Sources/ColdOpen06"
        ),
    ],
    swiftLanguageModes: [.v5]
)

// swift-tools-version:6.0
import PackageDescription

// BridgeSmoke: Windows executable that exercises ABI v0 end to end through
// packages/SwiftRightBridge (window, hand-authored tree, measurement at two widths,
// AX Invoke, typed character, clean quit). Builds on macOS too (it then reports
// "unsupported platform" at run time).
//
// Windows build needs the ComCtl v6 manifest link flags (GPUI's TaskDialogIndirect):
//   swift build -c release -Xlinker /MANIFEST:EMBED -Xlinker /MANIFESTDEPENDENCY:"type='win32' name='Microsoft.Windows.Common-Controls' version='6.0.0.0' processorArchitecture='*' publicKeyToken='6595b64144ccf1df' language='*'"
// (see scripts/build-smoke.ps1). The flags are supplied by the consumer invocation, not
// by a package manifest (no unsafeFlags).
let package = Package(
    name: "BridgeSmoke",
    platforms: [.macOS(.v14)],
    dependencies: [
        .package(path: "../../packages/SwiftRightBridge"),
    ],
    targets: [
        .executableTarget(
            name: "BridgeSmoke",
            dependencies: [.product(name: "SwiftRightBridge", package: "SwiftRightBridge")],
            path: "Sources/BridgeSmoke"
        ),
        // SR0 T4: a fixed scene (image, text + underline, clips, translate) whose rendered pixels scripts/drive-pixels.ps1 asserts.
        .executableTarget(
            name: "BridgePixels",
            dependencies: [.product(name: "SwiftRightBridge", package: "SwiftRightBridge")],
            path: "Sources/BridgePixels"
        ),
    ],
    swiftLanguageModes: [.v5]
)

// swift-tools-version:6.0
import PackageDescription

// SliceApp: packageable SwiftRight example. One shared SwiftUI-shaped editor screen (same source on
// macOS and Windows) with SDK-owned bootstrap: a SwiftUI App on macOS, and on Windows the fresh runtime
// plus SwiftRightBridge (explicit renderer load, typed startup errors).
//
// Build:
//   macOS:    swift build -c release
//   Windows:  run scripts/build-windows.ps1 through `win` (ComCtl v6 + DPI manifest must be embedded, and the exe
//             linked as a GUI-subsystem program with /SUBSYSTEM:WINDOWS /ENTRY:mainCRTStartup, by the consumer link
//             flags, not by this manifest: no unsafeFlags).
let package = Package(
    name: "SliceApp",
    platforms: [.macOS(.v14)],
    dependencies: [
        .package(path: "../../probes/sr0-s/fresh-runtime"),
        .package(path: "../../packages/SwiftRightBridge"),
    ],
    targets: [
        .executableTarget(
            name: "SliceApp",
            dependencies: [
                .product(name: "SwiftRightRuntime", package: "fresh-runtime", condition: .when(platforms: [.windows])),
                .product(name: "SwiftRightBridge", package: "SwiftRightBridge", condition: .when(platforms: [.windows])),
            ],
            path: "Sources/SliceApp"
        ),
    ],
    swiftLanguageModes: [.v5]
)

